import re


def _chiave(testo):
    testo = re.sub(r"\s+", " ", (testo or "").strip()).rstrip(".:;,-").strip()
    return testo.casefold()[:220]


def semina(apps, schema_editor):
    """Il catalogo parte da quello che è già stato scritto: titoli e quante volte."""
    Voce = apps.get_model("tasks", "CatalogoVoce")
    voci = {}

    def aggiungi(tipo, testo, nota="", durata=None):
        testo = re.sub(r"\s+", " ", (testo or "").strip())[:220]
        k = _chiave(testo)
        if len(k) < 3:
            return
        v = voci.setdefault((tipo, k), {"testo": testo, "usi": 0, "nota": "", "durata": None})
        v["usi"] += 1
        if nota and not v["nota"]:
            v["nota"] = str(nota)[:500]
        if durata and not v["durata"]:
            v["durata"] = durata

    Riga = apps.get_model("tasks", "MeetingAgendaItem")
    for titolo, nota, durata, fonte, issue, action in Riga.objects.values_list("titolo", "nota", "durata_minuti", "source", "issue_id", "action_id").iterator():
        if issue or action or str(fonte or "").startswith(("tappa:", "meeting_issue", "meeting_action")):
            continue
        aggiungi("ODG", titolo, nota, durata)
    for (titolo,) in apps.get_model("tasks", "MeetingActionItem").objects.values_list("title").iterator():
        aggiungi("AZIONE", titolo)
    for (titolo,) in apps.get_model("tasks", "MeetingIssue").objects.values_list("title").iterator():
        aggiungi("PROBLEMA", titolo)
    for (titolo,) in apps.get_model("tasks", "Task").objects.filter(project__isnull=False).exclude(category__tappa__gt="").values_list("title").iterator():
        aggiungi("ATTIVITA", titolo)
    Voce.objects.bulk_create([
        Voce(tipo=t, chiave=k, testo=v["testo"], usi=v["usi"], nota=v["nota"], durata_minuti=v["durata"])
        for (t, k), v in voci.items()
    ], batch_size=200)


